const resolved_gaps = [
  g('D02-B01', 'Ders bir hocanın bir dönemdeki ders açılışıdır: tek sahip (sahip_kisi_id), altında şubeler; tekillik etkin dersler arasında (dönem, sahip, kod). Aynı kodu farklı hocalar ayrı ders olarak açar.', 'Plan dersi tek hocaya bağlıyor (plan.html#kararlar-indirme), asistan ve ortak hoca sonraya kaldı (plan.html#kararlar-roller); yetki tek sütunla denetlenir, genişleme yolu dersYetkisi (D02-A09).'),
  g('D02-B02', 'Program saati derse bağlıdır ve şube kümesi taşır (program_saati_subeleri); oturum üretimde kümeyi kopyalar (oturum_subeleri). Kayıt kabulü ve indirme "öğrencinin şubesi oturumun kümesinde mi" sorusuyla yapılır (oturumSubeleri).', 'Farklı saatli şubeleri de birlikte işlenen şubeleri de tek yapı karşılar (teknik.html#kod-veri-modeli); başka şubenin oturumu öğrenciye inmez.'),
  g('D02-B03', 'Oturum bir program saatinin bir günkü oluşumudur; ardışık saatler tek program saatinde (blok) toplanır, aynı gün ayrık iki buluşma iki oturumdur. API ve panel oturumu tarihle değil kimlikle adresler.', 'Sözlükteki "tek buluşma" tanımı (plan.html#sozluk) ve blok ders kuralı (plan.html#kararlar-kafa-sayisi); D02-C01\'in çözümü.'),
  g('D02-B04', 'Program saati ve oturum türe göre açık ders saati sayısı taşır (teori_saat, uygulama_saat; toplam 1 ile 12); süreden türetilmez.', 'Ders saati 50 dakika olduğundan 10:00 ile 11:50 iki saattir (tasarim.html#ph-home); karışık blok tek oturumda kalır, hak formülü türe göre T ister (plan.html#devam-uyari-seviyeleri).'),
  g('D02-B05', 'Program kaydedilince dönemin bütün oturumları aynı işlemde üretilir; her değişiklikte yalnız başlamamış oturumlar packages/core/src/dersler içindeki saf plan fonksiyonuyla yeniden hesaplanır ve fark yazılır.', 'Telefon kalan planlı saatleri ve sonraki oturumu yerelde hesaplar, pencere internetsiz açılır; ders başına yaklaşık 30 satır küçük bir yazımdır; tatil ve iptal kararı sunucuda kalır (plan.html#gun-kenar-durumlar).'),
  g('D02-B07', 'Tatil tarih aralığı ve isteğe bağlı yarım gün başlangıç saatidir; o gün tatil saatinden önce başlayan oturum kalır. Sonradan girilen tatil gelecekteki oturumu iptal (tatil) yapar, silmez; tatil kalkınca oturum geri gelir (hoca o arada iptal etmediyse).', 'Basit ve izlenebilir; iptal oturumun kimliği internetsiz telefondan gelen kayıt için geçerli kalır, son karar sunucudadır.'),
  g('D02-B08', 'Dönem genel akademik dönemdir (yıl ve yarıyıl); birim ile dönem çifti birim_donemleri satırında takvimi ve kilidi taşır.', 'Yoklama kaydının tekil ve bölme anahtarı tek dönem kimliği ister (teknik.html#veritabani-donem-alani); farklı birimden ders alan çift anadal öğrencisi aynı dönemde kalır; D12-B13 ile aynı.'),
  g('D02-B09', 'Takvim ayrı varlıktır; birden çok birim aynı takvime bağlanır, ayrı takvimli birim kendi takvimine bağlanır.', 'Tek genel takvim varsayılmaz (plan.html#hoca); ortak tarih bir kez girilir, alan alan geçersiz kılma mantığı gerekmez.'),
  g('D02-B10', 'Birim türleri fakülte, enstitü, yüksekokul, meslek yüksekokulu, konservatuvar; bölüm birimin alt satırıdır ve takvimi yoktur. Ders birimini kendisi taşır; panel varsayılanı hocanın bölümünün biriminden önerir.', 'Takvim ve kilit fakülte ve enstitü düzeyinde (plan.html#hoca); servis dersinde hocanın birimi dersinkinden farklı olabilir. D02-C03\'ün çözümü.'),
  g('D02-B11', 'Kod ve ad serbest metindir: NFC, baş ve son boşluk silinir, çoklu boşluk teke iner; kod ayrıca Türkçe kuralla büyür (Intl kullanmadan). Tekillik etkin dersler arasında (dönem, sahip, kod) ve derste şube etiketi. Kod ve ad kilitten önce değişir ve denetim kaydına dersKodu ve dersAdi alan adlarıyla yazılır (D09\'un yasak alan adları kod ve ad ile çakışmasın).', 'AKSİS\'e otomatik bağlantı yok, ders kataloğu gerekmez; hoca özeti AKSİS\'teki dersle elle eşleştirir (plan.html#acik-aksis).'),
  g('D02-B12', 'Derslik serbest metindir (1 ile 40 karakter); program saatinde ve oturumda kopyası vardır, tek oturumda değiştirilebilir.', 'Aşama 3\'te sınıf konumu telefona gönderilmiyor (plan.html#asama23-gps), Aşama 2 eşleştirmesi tarayıcı ile ders arasında; katalog gerekmez.'),
  g('D02-B13', 'Aynı gün içinde saat, derslik ve saat sayısı değişikliğinde kimlik korunur, önceki değerler oturum_degisiklikleri satırına yazılır. Gün değişikliği taşımadır: telafi ucunda eskisiniIptalEt ile eski oturum iptal (tasindi), yenisi telafi olarak aynı işlemde açılır. Oturum hiç silinmez.', 'Kayıtlar kimlikle oturuma bağlı kalır; eski anlar D07\'nin internetsiz kayıt kararında kanıttır (plan.html#gun-kenar-durumlar).'),
  g("D02-B14", "Değişiklik yalnız başlangıcı saat arayüzüne göre gelecekte olan oturumlara uygulanır ve yeni başlangıç da gelecekte kalmalıdır; program saatinde isteğe bağlı geçerlilik aralığı vardır ve geçerlilikleri ayrık iki saat aynı gün aynı saatte şube paylaşabilir; başlamış oturumda yalnız \"Ders yapıldı mı?\" cevabı, kafa sayısı ve D04'ün ders içi ayarları değişir; kilitli dönemde yalnız cevapsız oturumun cevabı yazılır. Mimar onayıyla (I093): haftalık program kaydı başlamamış bugünkü oturumu şimdiye ya da geçmişe taşıyacaksa oturuma dokunmaz ve BUGUNKU_OTURUM_KORUNDU uyarısı döner; tekil PATCH'in 409 DERSLER_OTURUM_BASLAMIS reddi kalır.", "Geçmiş sayım sessizce değişmez; geçmişi düzeltmenin yolu denetim kayıtlı düzeltmedir (D09); bitmiş ve penceresiz oturum yaratılmaz. Bütün program kaydını reddetmek hocanın gelecek haftalarını da bekletirdi (I093)."),
  g('D02-B18', 'Onaysız oturum bitmiş, planlı ve yapıldı bilgisi olmayan oturumdur; panelde ve hoca telefonunda listelenir. "Yapıldı" cevabı kafa sayısız yapıldı yapar. "Yapılmadı" cevabından sonra (ya da iptal oturuma) gelen kafa sayısı çelişki açar: yapildi boşalır, oturum listede çelişkili görünür. İptal ve çelişkili oturumda "yapılmadı" yalnız çelişkiyi kapatır (durum iptal, yapildi boş), "yapıldı" oturumu planlıya döndürür ve sürüm alır. Toplu cevap ucu vardır; her cevap denetim kaydına yazılır.', 'Kafa sayısı internetsiz kuyrukta gecikebilir; çelişki sessizce çözülürse sayım değişir; dönem sonu çıktısı zaten cevap bekliyor (plan.html#kararlar-kafa-sayisi); iptal oturumda yapildi CHECK ile hep boştur.'),
  g('D02-B19', 'Kilit otomatiktir: kilit anı son günün ertesi 00:00 Europe/Istanbul; durum her okumada saat arayüzünden türetilir, donem_kilidi işi yalnız kalıcı yan etkileri uygular; kilit_ani kilitlenmiş takvim satırından aynı deyimde hesaplanır (bağ PUT FOR SHARE, takvim PUT FOR UPDATE); yönetici ekranı tarihi ve durumu gösterir.', 'Plan kilidi son güne bağlıyor ve süre en geç o gündür (plan.html#devam-donem-sonu); iş gecikse de kilit doğru görünür; kural için SQL now() yok (teknik.html#testler-veritabani-sifirlama); D14-B09 ile aynı; eşzamanlı takvim ve bağ yazımı bayat kilit anı bırakmaz.'),
  g("D02-B20", "Kilitte: kilitDurumu doğru olur (D05 ve D07 son günden sonra gelen kaydı yalnız saklar); kayıtlı kilit adımları sira ile çalışır (D07 dogrulama.karar_kapanisi 10: onaysız Kendi beyanı sayılmış haliyle, kararsızlar denetim kaydıyla; D10 raporlar.gun_sonu_anligi 20: gün sonu anlığı işi kilit işleminde kuyruğa girer), sonra D02'nin arşiv ve devam adımları çalışır: birimin dersleri arşivlenir; program, telafi, iptal, düzenleme, şube, ders ayarı, devir ve D03 liste yazımı kapanır; cevapsız oturuma cevap ve D09 düzeltmesi sürer; kilit telefona iner, eski saat belgesi ve QR anahtarları kilitliBirimDonemleri ile bırakılabilir. Son gün gerekçeyle ileri alınırsa kilitle arşivlenen dersler etkin olur ve kilit yeni anda yeniden uygulanır (D02-A05).", "Plan kilitten sonra sayımın ancak denetim kaydı bırakan düzeltmeyle değişeceğini söylüyor (plan.html#kararlar-gonderme-suresi); düzeltme yolu açık kalmalı. Adım sırası mimar kararıdır (I034, I049, A5)."),
  g('D02-B25', 'Birim ve dönemin takvimi bağlı değilse ya da dönem kilitliyse ders açma ve program kaydı açık hata koduyla reddedilir (DERSLER_TAKVIM_YOK, DERSLER_DONEM_KILITLI); ders açmak için ayrı onay yoktur; inceleme hesabı ders açamaz.', 'Oturum üretimi takvim ister; hoca zaten onaylıdır; sıra hatası çıkmaz, ilk yönetici takvimi önce girer; inceleme hesapları yalnız deneme dersini görür (plan.html#kararlar-inceleme-hesaplari).'),
  g('D02-B26', 'Yoklama süresi ders ayarıdır (boş: süre seçilmedi); oturum üretimde kopyalar; ayar değişince başlamamış ve süresi telafide elle verilmemiş oturumlarda güncellenir ve pencere D04 dinleyicisiyle yeniden hesaplanır; ders içi değişiklik D04\'ün pencere tablosundadır.', 'Plan "hoca ders ayarında süre seçtiyse" diyor (plan.html#kararlar-inceleme-hesaplari, Yoklama penceresi); hocanın telafiye açıkça verdiği süre ezilmez.'),
  g('D02-B27', 'Takvim yazımı aynı işlemde takvim_oturumlarini_yenile işini koyar; iş dersleri tek tek, her birini kendi işleminde yeniden hesaplar; fark temelli olduğundan iki kez çalışmak sonucu değiştirmez. Gece çalışması (01:55, D14 çizelgesinde satır olarak; I007) yalnız anları ve kilit anını onarır.', 'Bir birimde yüzlerce ders var, tek istekte hepsi uzun sürer; işler veritabanı işlemiyle birlikte kuyruğa girer (teknik.html#sunucu-arka-plan).'),
  g('D02-B28', 'Çakışma: iki planlı oturumun [başlangıç, bitiş) aralıkları kesişirse. Öğrenci eşleşmesi liste satırının öğrenci numarasıyla (D03 listeKaynagiKaydet ile kaydolan etkinSatirlar); ikinci programın listesindeki aynı numara dahil, farklı numarayla iki programda olan öğrenci eşleşmez (iki hesap gerekir, D03 kuralı). Panelde ders sayfasında liste satırı kimliği, öbür dersin kodu, adı ve saatleri; ayrı tablo yok; 2000 öğeyi aşan sonuç 422 API_SONUC_COK_BUYUK.', 'Plan çakışmanın hocalara gösterilmesini ve çift anadal listeleri arasında da denetlenmesini istiyor (plan.html#kararlar-kafa-sayisi); "tek derse yoklama" kararı D04 ve D07\'de kalır.'),
  g('D02-B29', 'İnen ders satırı: kod, ad, hocanın görünen adı (D01.kisiGetir), birimId, donemId, takipBaslangici, teori ve uygulama p, süre, QR ayarı, durum, arşiv nedeni, şubeler. Program saati satırı: gün, saatler, saat sayıları, derslik, geçerlilik, şubeler. Oturum satırı: tarih, yerel saatler, UTC anlar, saat sayıları, derslik, süre, QR ayarı, tür, durum, iptal nedeni, kısa kod, şubeler. Kilit satırı (kimlik birimId:donemId): takvimId, son gün, kilit anı, uygulandı. Tatil satırı: takvimId ile. Telefon dersin son gününü ve son haftasını ders satırındaki birimId ve donemId ile kilit satırından, tatillerini kilit satırındaki takvimId ile bulur. Kafa sayısı ve yapıldı inmez.', 'Tasarımdaki Bugün ekranı bu alanları gösteriyor (tasarim.html#ph-home); telefon hak uyarısını yerelde hesaplar (p gerekir); son hafta hatırlatması ders başına son gün ister (plan.html#devam-donem-sonu, D06-B16); hoca adı başka öğrencinin verisi değil.'),
  g("D02-B30", "Deneme dersi: derste deneme_dersi işareti, birimsiz, süresiz ve kilitsiz inceleme döneminde. İtme modeli: D01'in inceleme_hesaplari_kurulumu işi tek işlemde hocayı kurar, D02.denemeDersiniKur(tx, hocaKisiId) ile dönemi, dersi ve şube 1'i yoksa kurdurur, hoca değiştiyse dersi ona devrettirir ve dönen şubeye D03.denemeListesiniKur ile satırı kurdurur; deneme_dersi_oturumlari yalnız var olan deneme dersinin her gün 00:00 ile 24:00 oturumunu 14 gün ileriye üretir. Onaysız liste, çakışma, kilit, dönem arası, ölçüm ve raporlar dersi dışlar.", "Kayıt oturuma bağlı olduğundan her an açık bir oturum gerekir; silinirse sunucu yeniden kurar (plan.html#kararlar-inceleme-hesaplari); tek işlem yarım ders ya da listesiz deneme dersi bırakmaz (I003, I005)."),
  g('D02-B31', 'Ekle-bırak bitişi bilgi alanıdır: takvimGetir ile D03\'e gider, geç eklenen öğrencide seçim ekranı Md.9/4 seçeneğini açıklamayla gösterir; varsayılan değişmez, sunucu kuralı yok.', 'Plandaki varsayılan ekle-bırak seçeneğidir (plan.html#devam); kuralı değiştirmek ürün kararı olurdu.'),
  g("D02-B32", "Son hafta: birimin son günü dahil geriye 7 takvim günü (İstanbul). Son oturum: dersin iptal edilmemiş son oturumu, son ders günü onun tarihi. Son gün ve kilit anı kilit genel kaynağındaki birim dönemi satırıyla telefona iner; D06 ve D08 bunu kullanır (I040).", "Gönderme süresi kuralıyla aynı ölçü (plan.html#kararlar-gonderme-suresi); telefon hatırlatmayı internetsiz hesaplar (plan.html#devam-donem-sonu); D08-B23 ile aynı."),
  g('D02-B33', 'Takvim alanları ders_baslangic, ders_bitis, ekle_birak_bitis, devamsizlik_son_gun (hepsi zorunlu date); tatiller ve sınav haftaları ayrı tablolarda. CHECK: ders başlangıcı < ders bitişi <= son gün, ekle-bırak bitişi <= ders bitişi.', 'Son gün ders bitişine eşit olabilir (Eczacılık örneği, plan.html#devam-donem-sonu); ekle-bırak dersler başlamadan bitebilir.'),
  g('D02-B34', 'Yarıyıl metin ve CHECK: guz, bahar, yaz (yaz okulu ilk sürümde kullanılmasa da değer var); inceleme yalnız deneme dersinin dönemi; cevapta x-extensible-enum.', 'Liste sonradan genişlerse istemciler kırılmaz (teknik.html#sunucu-mimari).'),
  g('D02-B35', 'Dönem arası: en az bir etkin ve deneme olmayan dersi olan, dersleri başlamış ve kilidi gelmemiş hiçbir birim dönemi yoksa (inceleme dönemi hariç); birimin pasif olması hesaba girmez. Tek fonksiyon donemArasiMi (dış yüzde; bileşim kökü app.ts ve server.ts parametreyle verir, I006); yönetici kilit ekranı aynı değeri gösterir.', 'En düşük sürüm uygulama genelinde tek değerdir ve yalnız dönem arasında yükselir (plan.html#dagitim-guncelleme-ilkesi); pasif birimin süren dersleri de dönem içidir; D13-B17 ile aynı tanım.'),
  g('D02-B36', 'Arşiv salt okunurdur ve etkin listelerden çıkıştır. Kilitte birimin dersleri kendiliğinden arşivlenir (telefonda Dönem kapandı olarak kalır). Hoca, başlamış ve iptal edilmemiş oturumu olmayan kendi dersini arşivleyebilir; gelecekteki oturumlar iptal (arsiv) olur, ders telefonlardan kalkar. Sahibin hesabı silinince dersleri hoca_silindi nedeniyle arşivlenir (plan.html#kararlar-hesap-silme, D02-A07); deneme dersi arşivlenmez, D01 kurulum işi denemeDersiniKur ile yeni inceleme hocasına devrettirir. Raporlar arşivli dersi gösterir.', 'Yanlış açılan dersi kaldırmanın silmesiz yolu (plan.html#devam-donem-sonu). Kayıt ancak başlamış oturuma verilebildiğinden D02 bu koşulu yoklama kayıtlarını okumadan denetler (contracts.json\'da D02 D05\'i okumaz).'),
  g('D02-B37', 'İndirme D06\'nın sözleşmesiyle yapılır (D06-B15, D06 tipler): D02 beş genel kaynak kaydeder (dersler, program_saatleri, oturumlar, takvim_tatilleri, kilit); her biri degisenler(tx, { kapsam, surumden, surumeKadar, adet }) ile kapsam.dersler, kapsam.subeler ve kapsam.birimler süzgecinden geçen ve sürümü (surumden, surumeKadar] aralığında olan satırları sürüm sırasıyla en çok adet kadar döner; surumden null tam indirmedir, sayfayı D06 keser. Tatil satırının indirme sürümü GREATEST(tatil sürümü, bağlı birim dönemi sürümü): bağ değişince ya da ders yeni birime taşınınca birim dönemi damgalanır ve yeni takvimin eski tatilleri aralığa girer. Kapsam değişikliği (sonradan eklenen öğrenci, devir, hoca arşivi, birim değişikliği) D06\'nın baştan indirmesiyle çözülür: öğrenci kapsam kaynağı D03\'ün, personel kapsam kaynağı D02\'nin (D02 yalnız bunu kaydeder, I013, I094; sahip olunan derslerin şube, ders ve birim kümeleri; degistiMi, kişinin sahip ya da sahiplik_gecmisi içinde önceki sahip olduğu bir dersin kapsam_degisim_surumu imleçteki kapsamSurumu\'ndan büyükse true). silindi yalnız imleçten sonra değişip görme kapsamından çıkan satırda: şubesi kümeden çıkarılan öğrenciye program saati ve oturum, hoca arşivinde öğrenciye ders satırı (o dersin öbür satırları dönmez). Pasif liste satırında ders telefonda kalır (D03-B13). Kaldırılan program saati ve tatil silindi: true ile, oturum iptal durumuyla iner; kilitle ya da sahipsiz arşivlenen ders kilit anından 180 gün sonrasına kadar kapsamda kalır (başlangıç değeri, telefon aynı kuralla yerel dersi siler).', 'D06 kapsam değişikliğinde baştan indirir, kapsam olayı mantığı gerekmez; imleçten eski sürüm dönen kaynak sayfa kesmesini ilerletmez; öğrenci iptali görür, değişiklik sürümü tek sayaçtan (teknik.html#kod-veri-modeli).'),
  g('D02-B38', 'Oturum kısa kodu sütunu, dizisi ve tekil dizini ilk göçte açılır; her oturuma üretimde verilir; 1 ile 9.999.999.999 arası.', 'Sonradan eklemek dolu tabloda doldurma ve dizin ister; önce genişlet ilkesine uygun (teknik.html#telefon-kamera-qr).'),
  g('D02-B39', "Tarih genişletme packages/core/src/dersler içinde saf fonksiyondur (sivil tarih ve saatle çalışır, Intl kullanmaz). Yerel saatten UTC ana çeviri yazımla aynı SQL deyiminde (tarih + saat) AT TIME ZONE 'Europe/Istanbul' ile yapılır; takvim işinin gece çalışması başlamamış oturumlarda eşitliği denetleyip düzeltir. D04-B21'deki Node Intl önerisi seçilmedi.", 'Intl yalnız UTC\'den yerele biçimler, tersi elle yazılmış bir yaklaşım döngüsü ister; API ve işçi süreçleri yayın sırasında farklı saat dilimi verisi taşıyabilir, veritabanı tek kaynaktır; sabit +03:00 saat dilimi kuralı değişirse sessizce kayar.'),
  g('D02-B40', 'Ders açma ve değişikliği, arşiv, kilitten dönüş, devir, şube, program (özet ve saat başına), telafi, oturum düzenleme ve iptali, yapıldı cevabı, yeniden üretim, birim, bölüm, dönem, takvim, tatil, birim dönemi bağı ve kilit D09.denetimeYaz ile yazılır. Her dersler.* olay türünün onceki, sonraki ve ayrinti Zod şeması packages/contracts/src/dersler.ts\'te; alan adları D09\'un yasak adlarıyla çakışmaz (dersKodu, dersAdi, birimAdi, bolumAdi, takvimAdi, tatilAdi, subeEtiketi); diziler sınırlıdır ve her olay 8 KB altında kalır: program ve tatil listeleri bütün olarak değil, değişen saat ve tatil başına ayrı olayla yazılır. İsim ve numara taşımaz. p değişikliğinin olayını D08 yazar. Olay türleri ve ayrıntı şemaları DERSLER_DENETIM_OLAYLARI haritasındadır, bileşim kökü D09.denetimOlaylariniKaydet ile kaydeder; dersId taşıyan her olay zarfta birimId de taşır, birimsiz deneme dersinin olayları dersi hedef { tur: DERS, id } ile anar (I045).', 'Program değişikliği sayımı değiştirir; itirazda kanıt ve Haksız devamsız hesabı için gerekir (plan.html#hedefler); D09 yasak alan adı ya da 8 KB aşımında çağıranın işlemini geri aldırır, doğal { kod, ad } biçimi ders PATCH\'ini 500 ile düşürürdü.'),
  g('D02-B41', 'contracts.json kararıyla tek modül dersler (D02): bütün uçlar /v1/dersler altında, yönetici uçları /v1/dersler/yonetim altında; ders oturumu tablosu oturumlar, giriş oturumu tablosu giris_oturumlari (D01).', 'Uç sahibi yolun ikinci bölümünden okunur (teknik.html#sunucu); oturum sözcüğü şemada hep ders oturumudur.'),
  g('D02-B42', 'İlk sürümde yalnız aynı dersin şubeleri birlikte işlenir (oturum_subeleri); farklı kodlu iki ders birlikte işleniyorsa tek ders altında iki şube olarak açılır, listeler ayrı yüklenir; AKSİS özeti şube başınadır (D10-B12).', 'Birlikte işlenen şube var mı sorusu açık (plan.html#acik); en sade yol, sonra genişletilebilir.'),
  g('D02-B43', 'Program, telafi, iptal ve düzenleme panel uçlarıdır; hoca telefonu programı indirmeyle gösterir, "Ders yapıldı mı?" listesini ve cevabını internetliyken aynı uçlardan çağırır.', 'Plan bunları "Web paneli, hoca" altında sayıyor (plan.html#hoca); uçlar istemciden bağımsız, telefon ekranı sonra eklenebilir.'),
  g('D02-B44', 'Süre seçilmemiş derste de her bitmiş oturum için sorulur; toplu cevap ucu (200 oturuma kadar) hocanın işini kısa tutar.', 'Kayıt gelmiş oturumu kendiliğinden yapıldı saymak sayım tabanını hocasız değiştirir; hedef ders başına en çok 2 dakika (plan.html#hedefler).'),
  g('D02-B45', 'Kayıtların sayılan işareti ve kararı değişmez; "yapılmadı" ve iptal oturumun kayıtları ve saatleri sayımda oturum durumuyla dışlanır (D08 ve D10 oturumlariGetir ile okur). D02 her yapıldı, iptal ve program değişikliğinde aynı işlemde D08.devamHesaplaIsiKoy koyar; neden packages/contracts/src/devam.ts\'teki DEVAM_NEDENLERI sabitinden içe aktarılır: program, şube, telafi, iptal, düzenleme, arşiv ve takvim işi PROGRAM; kafa sayısı ve "Ders yapıldı mı?" YAPILDI; dönem kilidi KILIT. Tek yol: D08 D02\'ye kilit adımı ya da üretim dinleyicisi kaydetmez.', 'contracts.json\'a göre D02 D07\'yi çağırmaz; ham kayıt kanıt olarak kalır, hoca fikrini değiştirirse karar geri alınmaz; D07-B27 ile aynı; D08 YAPILDI işini ders çıkışı tepesinden sonraya geciktirir ve KILIT nedenini seviye geçmişine yazar (D08-A08).'),
  g("D02-B48", "İyimser eşzamanlılık: ders ve program yazımında dersler.duzenleme_no, takvimde takvimler.surum_no istekte ortak beklenenSurumNoSemasi'nın beklenenSurumNo alanıyla beklenen numara olarak gelir (D13, I071); uyuşmazsa 409 DERSLER_SURUM_UYUSMUYOR ve cevapta güncel hal; gövde kayıtlı halle aynıysa numaraya bakılmaz. Satır kilitleri tek sırayla alınır: takvimler, birim_donemleri, dersler, subeler, oturumlar; birden çok ders dersId sırasıyla (toplu cevap). Derse yazan her işlem önce ders satırını FOR UPDATE ile kilitler ve sahibi kilitten sonra yeniden denetler; şube pasifleştirme ve ders arşivi ders ve şube satırlarını FOR UPDATE alır ve liste kaynağını kilitten sonra sorar; D03 liste yazmadan önce aynı sırayla dersGetir ve subeGetir(..., { kilitle: 'paylasimli' }) ile FOR SHARE alır (I010, I011); kafaSayisiniYaz oturumu FOR NO KEY UPDATE ile kilitler.", "İki sekmenin ya da iki yöneticinin yazımı sessizce ezilmez; tekrarlanan aynı istek 409 almaz; tek kilit sırası kilitlenme döngüsünü önler, devirle yarışan yazım eski sahiple işlenmez, liste yazımı pasif şubede ya da arşivdeki derste etkin satır bırakmaz, kayıt eklemeleri kafa sayısını beklemez."),
  g('D02-B49', 'Sınırlar sözleşmede: ders başına 20 program saati ve 20 şube, dönemde ders başına 30 planlı telafi ve 400 planlı oturum (iptal satırlar sayılmaz); kod 20, ad 120, şube etiketi 20, derslik 40 karakter (uzunluklar ayrıca CHECK\'te); takvimde 60 tatil ve 10 sınav haftası; toplu cevapta 200 oturum; liste cevaplarında 1000 ile 2000 satır üst sınırı, aşılırsa kesik liste değil 422 API_SONUC_COK_BUYUK (D13-B13); iç okuma oturumlariGetir de kesmez, hata verir (büyük tarama oturumSayfasi ile).', 'Sınırsız liste tek istekte binlerce oturum üretir; satırlar silinmediği için iptaller sayılsaydı gün değişikliği sınırı tüketirdi; sayılar başlangıç değeridir, ilk dönemin gerçek verisiyle ayarlanır (D13-B13 deseni).'),
  g("D02-A12", "Liste kaynağı: dış yüzde listeKaynagiKaydet(kaynak: { etkinSatirlar(tx, suzgec: { subeIdleri?, ogrenciNolari? }) }) var; D03 kendi eklentisinde kaydolur, D02 hazır olurken kaydı denetler (yoksa açılmaz). Çakışma ucu, şube pasifleştirme ve ders arşivi kullanır; pasifleştirme ve arşiv önce ders ve şube satırlarını FOR UPDATE kilitler, etkinSatirlar'ı kilitten sonra sorar.", "Mimar kararı I004, I011, I096 (ACCEPT); contracts.json dış yüz listesinde. D02 D03'ü içe aktarmaz (kayıt deseni)."),
  g("D02-A13", "Deneme dersi itme modeliyle kurulur: denemeDersiniKur(tx, hocaKisiId): Promise<{ dersId, subeId }> dış yüzdedir; çağıran D01'in jobs/kimlik altındaki inceleme_hesaplari_kurulumu işidir ve aynı işlemde dönen şubeyle D03.denemeListesiniKur'u çağırır. deneme_dersi_oturumlari yalnız var olan deneme dersinin 14 günlük oturumlarını üretir, D01.incelemeHesaplari okumaz (o dış yüz yoktur), ders yoksa log yazıp durur; denemeDersi(tx) dış yüzü kaldırıldı (tüketicisi kalmadı); derslerKimlikDinleyicisi deneme işini kuyruğa koymaz, inceleme hocası silinince D01 kendi kurulum işini koyar.", "Mimar kararı I003 (ACCEPT) ve I005 (REJECT: önerilen çekme modeli reddedildi): tek işlem yarım ders ya da listesiz deneme dersi bırakmaz, inceleme hesabı kuralı D01'indir (plan.html#kararlar-inceleme-hesaplari)."),
  g("D02-A14", "donemArasiMi(tx, an?) dış yüzde kalır; D13 ve D15 onu içe aktarmaz, bileşim kökü parametre olarak verir: app.ts en düşük sürüm denetimine, server.ts yayın penceresine.", "Mimar kararı I006 (ACCEPT); altyapı modülleri alan modülünü içe aktarmaz (kayıt deseni)."),
  g("D02-A15", "takvim_oturumlarini_yenile gece onarımı 01:55 Europe/Istanbul kalır ve D14 çizelgesinde satır olarak yer alır.", "Mimar kararı I007 (ACCEPT): 03:00 ile 05:00 dışı, öbür günlük işlerden en az 5 dakika uzak (contracts.json, Gece çizelgesi)."),
  g("D02-A16", "Sürüm tek düzenekle gelir: D06.surumDamgasiIste(tx: Islem, damga: (surum: bigint) => Promise<void>): void (modules/esitleme/yaprak.ts) damgayı işleme bağlar; işlemin sahibi son adımda D06.surumAl(tx)'ı bir kez çağırır, sayaç bir kez artar ve bütün bekleyen damgalar aynı sürümle çağrılır; surumAl'sız biten damgalı işlem D12.islemSonuKancasi denetimiyle geri alınır (PaketBaglami.surumlaDamgala aynı işleve giden kısayoldur; D02'nin kuyruk öğesi yok). Üretim olayında sürüm geri çağrısı yoktur; dinleyiciler surumAl çağırmaz, sürümü surumDamgasiIste ile bırakır; D02 üretimin son adımında, dinleyicilerden sonra surumAl'ı bir kez çağırır. Olay sırası (satırlar, dinleyiciler, denetim, iş kuyruğu, sürüm) aynen; D04 için olaya oturumlar[].subeIdleri, onceki.yoklamaSuresiDk ve an, oturumGetir().degisiklikler[] öğesine oncekiYoklamaSuresiDk eklendi.", "Mimar kararı I008 ve I092 (CHANGE), I019 (ACCEPT) ve I018 (CHANGE): tek sayaç satırı karar boyunca kilitli kalmaz, iki damga düzeneği aynı işi iki yoldan yapmaz (ortak kural Sürüm damgası)."),
  g("D02-A17", "Adlar D02'ninkidir: dersYetkisi(tx, kimlik: Kimlik, dersId) üç parametrelidir ve yönetici kapsamını D13'ün ortak Kimlik tipindeki roller dizisinden okur (kapsamBirimId null bütün birimler; yoneticiKapsami parametresi yok); değer adı 'sahip'; OTURUM_TURLERI ve OTURUM_DURUMLARI sözleşmeden dışa açık; DEVAM_NEDENLERI D08'in sözleşmesinden içe aktarılır; oturumlariGetir tarih süzgeçleri tarihten ve tarihe; büyük taramalar oturumSayfasi; yalnız kendi dersleri hocaninDersleri ile. Beklenen sürüm ortak beklenenSurumNoSemasi alanı beklenenSurumNo; POST /v1/dersler durumlar [201, 200].", "Mimar kararı I009 (ACCEPT) ve I071 (CHANGE)."),
  g("D02-A18", "D03 karşılığı: öğrenci kapsam kaynağı D03'ündür (pasif satırın şubesi kapsamda kalır; dersler ve birimler subeGetir ve dersGetir ile doldurulur), D02 yalnız personel kapsam kaynağını kaydeder. subeGetir(tx, subeId, s?: { kilitle?: 'paylasimli' }) ve dersGetir(tx, dersId, s?: { kilitle?: 'paylasimli' }) seçenek verilince SELECT ... FOR SHARE okur; D03 liste yazmadan önce önce dersi, sonra şubeyi böyle kilitler. dersGetir açıklamasındaki 'D03 devirde sahipAtamaSurumu okur' notu kaldırıldı; devir D06'nın personel kapsamıyla çözülür. Deneme listesinin şubesi denemeDersiniKur'un dönüşünden gelir.", "Mimar kararı I010, I011, I013, I094 ve I096 (ACCEPT)."),
];

